class Solution {
  public long maxAlternatingSum(int[] nums) {
    int n = nums.length;
    long[] sq = new long[n];
    for (int i = 0; i < n; i++) sq[i] = (long) nums[i] * nums[i];
    java.util.Arrays.sort(sq);
    long total = 0;
    int positives = (n + 1) / 2;
    for (int i = 0; i < n; i++) total += i >= n - positives ? sq[i] : -sq[i];
    return total;
  }
}
